import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure proper types
    target_state["order_id"] = target_state["order_id"].astype("int64")
    target_state["last_seq"] = target_state["last_seq"].astype("int64")

    cdc_events["seq"] = cdc_events["seq"].astype("int64")
    cdc_events["order_id"] = cdc_events["order_id"].astype("int64")

    # Step 1: Deduplicate events by seq (keep first occurrence)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first").reset_index(drop=True)

    # Step 2: Apply replay guard - filter out events where seq <= last_seq for existing orders
    # Create a mapping of order_id to last_seq from target_state
    last_seq_map = dict(zip(target_state["order_id"], target_state["last_seq"]))

    # Mark events to skip based on replay guard
    def should_skip(row):
        order_id = row["order_id"]
        seq = row["seq"]
        if order_id in last_seq_map:
            return seq <= last_seq_map[order_id]
        return False

    cdc_events["skip"] = cdc_events.apply(should_skip, axis=1)
    cdc_events = cdc_events[~cdc_events["skip"]].drop(columns=["skip"]).reset_index(drop=True)

    # Step 3: Sort events by seq to apply in order
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # Step 4: Build new state by applying events
    # Initialize state from target_state
    state_dict = {}
    for _, row in target_state.iterrows():
        order_id = row["order_id"]
        state_dict[order_id] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"],
            "exists": True
        }

    # Track which orders have been touched and their last operation
    last_op_map = {}  # order_id -> (op, seq)

    # Apply each event in seq order
    for _, event in cdc_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]
        op = event["op"]

        if op == "I":
            # Insert or update (creates if missing, updates if exists)
            state_dict[order_id] = {
                "status": event["status"],
                "amount": event["amount"],
                "last_seq": seq,
                "exists": True
            }
            last_op_map[order_id] = ("I", seq)
        elif op == "U":
            # Update (creates if missing)
            if order_id not in state_dict:
                # Create new row
                state_dict[order_id] = {
                    "status": event["status"],
                    "amount": event["amount"],
                    "last_seq": seq,
                    "exists": True
                }
            else:
                # Update existing row
                state_dict[order_id]["status"] = event["status"]
                # Only update amount if not NULL
                if pd.notna(event["amount"]):
                    state_dict[order_id]["amount"] = event["amount"]
                state_dict[order_id]["last_seq"] = seq
            last_op_map[order_id] = ("U", seq)
        elif op == "D":
            # Delete
            if order_id in state_dict:
                state_dict[order_id]["exists"] = False
            last_op_map[order_id] = ("D", seq)

    # Step 5: Build new_state (only rows that exist)
    new_state_rows = []
    for order_id, state in state_dict.items():
        if state["exists"]:
            new_state_rows.append({
                "order_id": order_id,
                "status": state["status"],
                "amount": state["amount"],
                "last_seq": state["last_seq"]
            })

    new_state = pd.DataFrame(new_state_rows)
    if len(new_state) == 0:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    new_state = new_state.astype({
        "order_id": "int64",
        "status": "object",
        "amount": "float64",
        "last_seq": "int64"
    })

    # Step 6: Build tombstones (orders whose last operation is 'D')
    tombstone_rows = []
    for order_id, (op, seq) in last_op_map.items():
        if op == "D":
            tombstone_rows.append({
                "order_id": order_id,
                "deleted_seq": seq
            })

    tombstones = pd.DataFrame(tombstone_rows)
    if len(tombstones) == 0:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])

    tombstones = tombstones.astype({
        "order_id": "int64",
        "deleted_seq": "int64"
    })

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
